	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		ProductVariant
	 */
		public ProductVariant createProductVariant( CreateProductVariantCommand command ) {

		ProductVariant entity = new ProductVariant();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setProductVariantId( command.getProductVariantId() );
            entity.setSku( command.getSku() );
            entity.setBarcode( command.getBarcode() );
            entity.setTitle( command.getTitle() );
            entity.setWeight( command.getWeight() );
            entity.setRequiresShipping( command.getRequiresShipping() );
            entity.setWeightUnit( command.getWeightUnit() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of ProductVariant {0} ", entity.toString() );

		return entity;
	}

